    cat > /tmp/elysium-probe/run.py <<'PY_RUN'
"""Read-only pass 3 (dashboard_ro, web image, no network): card outcomes from execution prices of public
tracked wallets on each card token (HYPE per token unit; ratios only, so decimals and Agora's price units
cancel out), and how the card's own members fared."""
import json
import os
from collections import defaultdict
from datetime import datetime, timedelta, timezone

import sqlalchemy as sa

C = 99901
NOW = datetime.now(timezone.utc)
cards = json.load(open("/probe/cards3.json"))
toks = sorted({c[0] for c in cards})
eng = sa.create_engine(os.environ["DATABASE_URL"])
legs = defaultdict(list)
with eng.connect() as c:
    c.execute(sa.text("SET statement_timeout = '600s'"))
    for r in c.execute(sa.text("""
        SELECT token, wallet, kind, hype_wei, qty, block_time, tx_hash FROM trades
         WHERE chain_id = :c AND token = ANY(:t) AND kind IN ('BUY', 'SELL') AND confidence = 'high'
           AND hype_wei > 0 AND qty > 0 AND block_time >= :lo
         ORDER BY token, block_time, id"""), {"c": C, "t": toks, "lo": NOW - timedelta(days=33)}):
        legs[r[0]].append((r[5], r[1], r[2], int(r[3]), int(r[4]), r[6]))
print("legs", sum(len(v) for v in legs.values()), flush=True)


def out(kind, obj):
    print("DATA|" + kind + "|" + json.dumps(obj, default=str, separators=(",", ":")), flush=True)


for tok, at, tx, members in cards:
    t = datetime.fromisoformat(at)
    L = legs.get(tok, [])
    trig = [x for x in L if x[5] == tx and x[2] == "BUY"]
    if not trig:
        out("x", {"token": tok, "at": at, "ok": False})
        continue
    p0 = trig[0][3] / trig[0][4]
    res = {"token": tok, "at": at, "ok": True}
    # follower entry: the highest buy price paid by anyone within 90 s after the trigger (pessimistic)
    nxt = [x[3] / x[4] for x in L if t < x[0] <= t + timedelta(seconds=90) and x[2] == "BUY"]
    res["entry90"] = max(nxt) / p0 if nxt else None
    for hrs in (1, 6, 24, 72):
        w = [x for x in L if t < x[0] <= t + timedelta(hours=hrs)]
        res[f"hi_{hrs}h"] = max(x[3] / x[4] for x in w) / p0 if w else None
        res[f"sellhi_{hrs}h"] = max((x[3] / x[4] for x in w if x[2] == "SELL"), default=None)
        if res[f"sellhi_{hrs}h"]:
            res[f"sellhi_{hrs}h"] /= p0
        res[f"n_{hrs}h"] = len(w)
        upto = [x for x in L if x[0] <= t + timedelta(hours=hrs)]
        res[f"last_{hrs}h"] = upto[-1][3] / upto[-1][4] / p0 if upto else None
        res[f"lastat_{hrs}h"] = upto[-1][0] if upto else None
    lo24 = [x[3] / x[4] for x in L if t < x[0] <= t + timedelta(hours=24)]
    res["lo_24h"] = min(lo24) / p0 if lo24 else None
    res["last_px"] = L[-1][3] / L[-1][4] / p0
    res["last_at"] = L[-1][0]
    # members: buys from their first buy up to trigger+24h, sells up to trigger+72h
    mm = set(members)
    acc = defaultdict(lambda: [0, 0, 0, 0])   # buy hype, buy qty, sell hype, sell qty
    for x in L:
        if x[1] in mm and x[0] >= t - timedelta(minutes=30):
            if x[2] == "BUY" and x[0] <= t + timedelta(hours=24):
                acc[x[1]][0] += x[3]; acc[x[1]][1] += x[4]
            elif x[2] == "SELL" and x[0] <= t + timedelta(hours=72):
                acc[x[1]][2] += x[3]; acc[x[1]][3] += x[4]
    bh = sum(a[0] for a in acc.values()); bq = sum(a[1] for a in acc.values())
    sh = sum(a[2] for a in acc.values()); sq = sum(a[3] for a in acc.values())
    res["m_buy_hype"] = bh / 1e18
    res["m_sell_hype"] = sh / 1e18
    res["m_sold_frac"] = sq / bq if bq else None
    res["m_exit_x"] = (sh / sq) / (bh / bq) if sq and bq and bh else None
    res["m_pnl_hype"] = (sh - bh * min(1, sq / bq)) / 1e18 if bq else None
    res["m_winners"] = sum(1 for a in acc.values() if a[3] and a[1] and (a[2] / a[3]) > (a[0] / a[1]))
    res["m_sellers"] = sum(1 for a in acc.values() if a[3])
    out("x", res)
print("done", flush=True)
PY_RUN
    chmod 644 /tmp/elysium-probe/*
    docker compose run -T --rm --no-deps -v /tmp/elysium-probe:/probe:ro --entrypoint python web /probe/run.py 2>&1 | grep -v "^ Container\|Creating\|Created" || true
    rm -rf /tmp/elysium-probe
    ;;
  ui-smoke)
    docker compose run --rm --no-deps ui --ui-smoke
    ;;
  restart)
    docker compose restart tracker ui
    wait_healthy || true
    status
    ;;
  stop)
    docker compose stop tracker
    docker compose ps
    ;;
  *)
    echo "unknown action: $ACTION" >&2
    exit 2
    ;;
esac
